<?php
declare(strict_types=1);
require_once __DIR__.'/_common.php'; require_admin_role('admin'); $pdo=db(); $msg=''; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ try{ check_csrf($_POST['csrf']??null); $action=$_POST['action']??'';
 if($action==='create'){ $username=trim($_POST['username']??''); $pass=(string)($_POST['password']??''); $role=($_POST['role']??'editor')==='admin'?'admin':'editor'; if(strlen($username)<3||strlen($username)>80) throw new RuntimeException('El usuario debe tener entre 3 y 80 caracteres.'); if(strlen($pass)<10) throw new RuntimeException('La contraseña debe tener al menos 10 caracteres.'); $s=$pdo->prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)'); $s->execute([$username,password_hash($pass,PASSWORD_DEFAULT),$role]); $msg='Usuario creado correctamente.'; }
 elseif($action==='delete'){ $id=(int)$_POST['id']; $s=$pdo->prepare('SELECT username,role FROM users WHERE id=?');$s->execute([$id]);$u=$s->fetch(); if(!$u) throw new RuntimeException('Usuario no encontrado.'); if($u['username']===$_SESSION['admin_user']) throw new RuntimeException('No puedes eliminar tu propia cuenta.'); if($u['role']==='admin' && (int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin'")->fetchColumn()<=1) throw new RuntimeException('Debe quedar al menos un administrador.'); $pdo->prepare('DELETE FROM users WHERE id=?')->execute([$id]); $msg='Usuario eliminado.'; }
 }catch(Throwable $e){$error=$e->getMessage();}}
$users=$pdo->query('SELECT id,username,role,created_at,discord_username FROM users ORDER BY created_at DESC,id DESC')->fetchAll(); admin_header('Administradores','users'); ?>
<div class="eyebrow">NEXUS · EQUIPO</div><h1>Administradores y editores</h1><p class="muted">Crea cuentas para que otras personas puedan ayudarte a actualizar el contenido. Los administradores pueden gestionar estas cuentas; los editores pueden gestionar el contenido.</p>
<?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><?php if($error):?><div class="error-box"><?=e($error)?></div><?php endif;?>
<div class="admin-card"><h2>Crear usuario</h2><form class="admin-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Usuario<input name="username" minlength="3" maxlength="80" required></label><label>Contraseña<input name="password" type="password" minlength="10" required></label><label>Permisos<select name="role"><option value="editor">Editor — contenido</option><option value="admin">Administrador — contenido + usuarios</option></select></label><button class="btn primary" type="submit">Crear usuario</button></form></div><br>
<div class="admin-card"><h2>Usuarios existentes</h2><div style="overflow:auto"><table class="admin-table"><thead><tr><th>Usuario</th><th>Rol</th><th>Discord</th><th>Creado</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['username'])?></td><td><?=e($u['role'])?></td><td><?=e($u['discord_username']??'—')?></td><td><?=e($u['created_at'])?></td><td><?php if($u['username']!==$_SESSION['admin_user']):?><form method="post" onsubmit="return confirm('¿Eliminar este usuario?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn danger" type="submit">Eliminar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div><?php admin_footer(); ?>